<?php
declare(strict_types=1);require __DIR__.'/../bootstrap.php';if(PHP_SAPI!=='cli')exit("CLI only\n");$scanner=(string)file_setting('scanner_url','');$s=db()->query("SELECT * FROM file_objects WHERE scan_status='pending' AND status='pending' ORDER BY id LIMIT 20");while($f=$s->fetch()){$status='failed';$magic='';try{$u=file_asset_url($f);$ch=curl_init($u);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_RANGE=>'0-8191',CURLOPT_CONNECTTIMEOUT_MS=>700,CURLOPT_TIMEOUT_MS=>2500]);$sample=curl_exec($ch);curl_close($ch);if($sample!==false){$magic=(new finfo(FILEINFO_MIME_TYPE))->buffer($sample)?:'';}}catch(Throwable $e){}if(file_blacklisted($f['original_name'],$f['mime_type'])||in_array($magic,['application/x-dosexec','application/x-msdownload','application/vnd.android.package-archive'],true)){$status='infected';}elseif($scanner!==''){try{$payload=json_encode(['file_id'=>(int)$f['id'],'name'=>$f['original_name'],'mime'=>$f['mime_type'],'size'=>(int)$f['size_bytes'],'download_url'=>file_asset_url($f)]);$ch=curl_init($scanner);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$payload,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT_MS=>1000,CURLOPT_TIMEOUT_MS=>10000]);$body=curl_exec($ch);curl_close($ch);$r=json_decode((string)$body,true);$status=($r['clean']??false)?'clean':(($r['infected']??false)?'infected':'failed');}catch(Throwable $e){$status='failed';}}else{$status='failed';}if($status==='clean'){db()->prepare("UPDATE file_objects SET scan_status='clean',status='clean',updated_at=NOW() WHERE id=?")->execute([(int)$f['id']]);}elseif($status==='infected'){db()->prepare("UPDATE file_objects SET scan_status='infected',status='quarantined',updated_at=NOW() WHERE id=?")->execute([(int)$f['id']]);file_emit('file.expired',(int)$f['id'],['reason'=>'malware']);}else{db()->prepare("UPDATE file_objects SET scan_status='failed',updated_at=NOW() WHERE id=?")->execute([(int)$f['id']]);}}
